CREATE TABLE "User" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL);
CREATE TABLE "Place" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "category" TEXT NOT NULL, "description" TEXT NOT NULL, "openingHours" TEXT NOT NULL);
CREATE TABLE "Review" ("id" TEXT PRIMARY KEY, "placeId" TEXT NOT NULL REFERENCES "Place"("id") ON DELETE CASCADE, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "rating" INTEGER NOT NULL CHECK ("rating" BETWEEN 1 AND 5), "body" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("placeId", "userId"));
CREATE TABLE "TourSlot" ("id" TEXT PRIMARY KEY, "placeId" TEXT NOT NULL REFERENCES "Place"("id") ON DELETE CASCADE, "startsAt" TIMESTAMP(3) NOT NULL, "capacity" INTEGER NOT NULL CHECK ("capacity" > 0));
CREATE TABLE "Booking" ("id" TEXT PRIMARY KEY, "slotId" TEXT NOT NULL REFERENCES "TourSlot"("id") ON DELETE CASCADE, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "seats" INTEGER NOT NULL CHECK ("seats" > 0), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Booking_slotId_idx" ON "Booking"("slotId");
